    public class CustomerListService : BaseDataAccess, ICustomerListService
    {
        ICustomerSettingDataAccess _customerSettingDataAccess = null;
        public CustomerListService() : this(null) { }
        public CustomerListService(ICustomerSettingDataAccess customerSettingDataAccess)
        {
            _customerSettingDataAccess = customerSettingDataAccess ?? new CustomerSettingDataAccess();
